public int maximalRectangle(char[][] matrix) {
    if (matrix.length == 0) return 0;

    int m = matrix[0].length;
    int[] height = new int[m];
    int maxArea = 0;

    for (char[] row : matrix) {
        for (int i = 0; i < m; i++) {
            if (row[i] == '1') height[i]++;
            else height[i] = 0;
        }
        maxArea = Math.max(maxArea, largestRectangleArea(height));
    }

    return maxArea;
}
